create schema auth;do $$begin if not exists(select 1 from pg_roles where rolname='authenticated') then create role authenticated nologin;end if;end$$;create table auth.users(id uuid primary key);
create or replace function auth.uid() returns uuid language sql stable set search_path='' as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create table public.organizations(id uuid primary key,name text);create table public.profiles(id uuid primary key references auth.users(id),organization_id uuid references public.organizations(id),role text,active boolean);
create table public.clients(id uuid primary key,organization_id uuid not null references public.organizations(id),company_name text not null,trade_name text,contact_name text,document_number text,email text,phone text,website text,instagram text,segment text,lead_source text,status text not null,notes text,billing_contact_name text,billing_contact_email text,billing_contact_phone text,billing_contact_role text,primary_responsible_id uuid,created_at timestamptz default now(),updated_at timestamptz default now(),created_by uuid,updated_by uuid,deleted_at timestamptz);
create table public.contracts(id uuid primary key,organization_id uuid not null,client_id uuid not null,proposal_id uuid,status text,monthly_value numeric,billing_day integer,deleted_at timestamptz,created_at timestamptz default now());
create table public.invoice_installments(id uuid primary key,organization_id uuid not null,client_id uuid not null,contract_id uuid not null,reference_month date,installment_number integer,due_date date,amount numeric,received_amount numeric default 0,status text,paid_at timestamptz,idempotency_key text,provider_invoice_id text);
create table public.audit_log(id uuid primary key default gen_random_uuid(),organization_id uuid,actor_id uuid,action text,entity_type text,record_id uuid,before_data jsonb,after_data jsonb,source text,created_at timestamptz default now());
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path='' as $$begin new.updated_at=now();return new;end$$;
create or replace function public.current_organization_id() returns uuid language sql stable security definer set search_path='' as $$select organization_id from public.profiles where id=auth.uid() and active$$;
create or replace function public.current_user_role() returns text language sql stable security definer set search_path='' as $$select role from public.profiles where id=auth.uid() and active$$;
create or replace function public.is_active_user() returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=auth.uid() and active)$$;
create or replace function public.can_write() returns boolean language sql stable set search_path='' as $$select public.current_user_role() in('admin','manager')$$;
create or replace function public.capture_audit_log() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_log(organization_id,actor_id,action,entity_type,record_id,before_data,after_data,source) values(coalesce(new.organization_id,old.organization_id),auth.uid(),lower(tg_op),tg_table_name,coalesce(new.id,old.id),case when tg_op<>'INSERT' then to_jsonb(old) end,case when tg_op<>'DELETE' then to_jsonb(new) end,'database');return case when tg_op='DELETE' then old else new end;end$$;
